sys_script_include.script:
var IncentIQMetricReportUtil = Class.create();
IncentIQMetricReportUtil.prototype = {
    initialize: function() {},

    insertMetricRecord: function(statementGR) {

        if (!statementGR || !statementGR.isValidRecord()) {
            return;
        }

        var user = statementGR.getValue('user');
        var plan = statementGR.getValue('plan');
        var period = statementGR.getValue('fiscal_period');

        var userGR = statementGR.user.getRefRecord();
        var periodGR = statementGR.fiscal_period.getRefRecord();

        // ----------------------------------
        // 1. UPSERT CHECK (optional improvement)
        // ----------------------------------
        var metricGR = new GlideRecordSecure('x_ctans_incentnow_metric_report');

        metricGR.addQuery('user', user);
        metricGR.addQuery('plan', plan);
        metricGR.addQuery('fiscal_period', period);
        metricGR.query();

        if (metricGR.next()) {
            // update existing
        } else {
            metricGR.initialize();
            metricGR.user = user;
            metricGR.plan = plan;
            metricGR.fiscal_period = period;
        }

        // ----------------------------------
        // 2. DIMENSIONS
        // ----------------------------------
        metricGR.fiscal_year = periodGR.getValue('fiscal_year');
        metricGR.period_type = periodGR.getValue('period_type');
        metricGR.manager = userGR.getValue('manager');

        var dimension = userGR.getValue('business_dimension');

        if (dimension == 'business_unit') {
            metricGR.business_unit = userGR.getValue('business_unit');
        } else if (dimension == 'territory') {

            var util = new IncentNowUtils();

            if (util.isTerritoryExtensionActive()) {
                metricGR.x_ctans_territory_territory = userGR.getValue('x_ctans_territory_territory');
            } else {
                gs.warn(this.LOG + 'Territory selected on user profile but Territory extension/plugin is not active.');
            }
        }

        // ----------------------------------
        // 3. METRICS (from statement only)
        // ----------------------------------
        metricGR.total_commission = statementGR.getValue('total_commission');

        if (statementGR.getValue('target_quota'))
            metricGR.target_quota = statementGR.getValue('target_quota');

        if (statementGR.getValue('quota_attainment'))
            metricGR.quota_attainment = statementGR.getValue('quota_attainment');

        // ----------------------------------
        // 4. CREDIT AGGREGATION
        // ----------------------------------
        var creditGR = new GlideRecordSecure('x_ctans_incentnow_credit_results');
        creditGR.addQuery('user', user);
        creditGR.addQuery('plan', plan);
        creditGR.addQuery('fiscal_period', period);
        creditGR.query();

        var totalCreditAmount = 0;
        var totalTransactions = 0;

        while (creditGR.next()) {
            var aggType = creditGR.getValue('aggregation_type');
            var value = parseFloat(creditGR.getValue('credit_value')) || 0;
            var count = parseFloat(creditGR.getValue('count')) || 0;

            if (aggType == 'sum') {
                totalCreditAmount += value;
            } else {
                totalTransactions += count;
            }
        }

        var periodType = (periodGR.getValue('period_type') || '').toLowerCase();

        if (periodType != 'month') {

            var aggregate =
                new IncentNowStatementProcessor()
                ._aggregateFromMonthly(statementGR, periodGR);

            metricGR.total_credits = aggregate.total_credit || 0;
            metricGR.transaction_count = aggregate.total_transaction || 0;

        } else {
            metricGR.total_credits = totalCreditAmount;
            metricGR.transaction_count = totalTransactions;
        }

        metricGR.statement_id = statementGR.getUniqueValue();

        // ----------------------------------
        // 5. SAVE
        // ----------------------------------

        var result;

        if (metricGR.isNewRecord())
            result = metricGR.insert();
        else
            result = metricGR.update();
        return result;
    },

    type: 'IncentIQMetricReportUtil'
};
